function sk1040_table_exists(string $table): bool {static $c=[];if(isset($c[$table]))return $c[$table];if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$table))return false;try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$table]);return $c[$table]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$table]=false;}}
function sk1040_columns(string $table): array {static $c=[];if(isset($c[$table]))return $c[$table];if(!sk1040_table_exists($table))return $c[$table]=[];try{$q=db()->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);return $c[$table]=array_map('strval',$q->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){return $c[$table]=[];}}
function sk1040_tid(): int {try{if(function_exists('tenant_id'))return max(0,(int)tenant_id());if(function_exists('current_tenant')){$t=current_tenant();return max(0,(int)($t['id']??0));}}catch(Throwable $e){}return 0;}
function sk1040_uid(): int {try{$u=function_exists('current_user')?current_user():null;return max(0,(int)($u['id']??0));}catch(Throwable $e){return 0;}}
function sk1040_h(string $s): string {return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
function sk1040_visitor_hash(): string {$cookie=(string)($_COOKIE['sk1040_v']??'');if(!preg_match('/^[a-f0-9]{32}$/',$cookie)){$cookie=bin2hex(random_bytes(16));if(!headers_sent())setcookie('sk1040_v',$cookie,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);}return hash('sha256',$cookie.'|'.(string)($_SERVER['REMOTE_ADDR']??''));}
function sk1040_settings(bool $refresh=false): array {static $c=[];$tid=sk1040_tid();if(!$refresh&&isset($c[$tid]))return $c[$tid];$d=['tenant_id'=>$tid,'assistant_enabled'=>1,'booking_enabled'=>1,'guest_booking_enabled'=>1,'provider_inbox_enabled'=>1,'homepage_section_enabled'=>1,'search_logging_enabled'=>1,'booking_reminders_enabled'=>1,'max_results'=>18,'booking_min_notice_minutes'=>30];if(!sk1040_table_exists('local_assistant_settings_v1040'))return $c[$tid]=$d;try{$q=db()->prepare('SELECT * FROM local_assistant_settings_v1040 WHERE tenant_id=? LIMIT 1');$q->execute([$tid]);$r=$q->fetch();if(!$r){db()->prepare('INSERT IGNORE INTO local_assistant_settings_v1040(tenant_id) VALUES(?)')->execute([$tid]);$r=[];}return $c[$tid]=array_merge($d,$r?:[]);}catch(Throwable $e){return $c[$tid]=$d;}}
function sk1040_on(string $key): bool {$s=sk1040_settings();$f=$key.'_enabled';return !array_key_exists($f,$s)||(int)$s[$f]===1;}
function sk1040_first(array $r,array $keys,$default=''){foreach($keys as $k)if(isset($r[$k])&&$r[$k]!==''&&$r[$k]!==null)return $r[$k];return $default;}
function sk1040_image(array $r): string {return (string)sk1040_first($r,['image_url','image','thumbnail_url','thumbnail','cover_url','cover_image','featured_image','logo_url'],'');}
function sk1040_title(array $r): string {return (string)sk1040_first($r,['title','name','full_name','display_name','label'],'Untitled');}
function sk1040_desc(array $r): string {return (string)sk1040_first($r,['tagline','short_description','summary','description','specialization','cuisine','address','area'],'');}
function sk1040_entity_url(string $type,int $id): string {$m=['business'=>'/business.php?id=','product'=>'/product.php?id=','property'=>'/property.php?id=','job'=>'/jobs.php?id=','event'=>'/events.php?id=','doctor'=>'/doctor-online.php?id=','hotel'=>'/hotels.php?id=','restaurant'=>'/discover-v1020.php?type=restaurants&id='];return isset($m[$type])?$m[$type].$id:'#';}
function sk1040_bookable(string $type): bool {return in_array($type,['business','doctor','hotel','restaurant'],true);}
function sk1040_intents(string $q): array {$x=mb_strtolower($q);$map=['doctor'=>['doctor','dr ','clinic','health','appointment'], 'restaurant'=>['restaurant','food','dinner','lunch','cafe','bbq'], 'hotel'=>['hotel','room','stay','booking'], 'property'=>['property','house','home','plot','rent','apartment'], 'product'=>['product','phone','mobile','laptop','tv','price','buy','shop'], 'job'=>['job','vacancy','career','work'], 'event'=>['event','expo','concert','festival'], 'business'=>['business','service','shop','mechanic','electrician','plumber','salon']];$out=[];foreach($map as $k=>$words)foreach($words as $w)if(str_contains($x,$w)){$out[]=$k;break;}return array_values(array_unique($out));}
function sk1040_generic_search(string $table,string $type,string $term,array $searchFields,int $limit=5,array $extra=[]): array {if(!sk1040_table_exists($table))return [];$cols=sk1040_columns($table);$fields=array_values(array_filter($searchFields,fn($f)=>in_array($f,$cols,true)));if(!$fields)return [];$or=[];$p=[];$where=[];if(trim($term)!==''){foreach($fields as $f){$or[]="`$f` LIKE ?";$p[]='%'.$term.'%';}$where[]='('.implode(' OR ',$or).')';}$tid=sk1040_tid();if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='tenant_id=?';$p[]=$tid;}if(in_array('status',$cols,true))$where[]="status NOT IN ('deleted','inactive','disabled','rejected','draft')";foreach($extra as $k=>$v)if(in_array($k,$cols,true)){$where[]="`$k`=?";$p[]=$v;}try{$sql='SELECT * FROM `'.$table.'` WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT '.max(1,min(12,$limit));$st=db()->prepare($sql);$st->execute($p);$rows=$st->fetchAll()?:[];$out=[];foreach($rows as $r){$id=(int)($r['id']??0);if($id<1)continue;$price=sk1040_first($r,['sale_price','price','amount','fee_amount','price_per_night','average_cost'],'');$provider=(int)sk1040_first($r,['owner_user_id','owner_id','user_id'],0);$out[]=['type'=>$type,'id'=>$id,'title'=>sk1040_title($r),'subtitle'=>sk1040_desc($r),'image'=>sk1040_image($r),'price'=>$price,'url'=>sk1040_entity_url($type,$id),'bookable'=>sk1040_bookable($type),'provider_user_id'=>$provider];}return $out;}catch(Throwable $e){return [];}}
function sk1040_search(string $query): array {$query=trim(preg_replace('/\s+/u',' ',$query));if(mb_strlen($query)<2)return ['query'=>$query,'results'=>[],'intent'=>[],'message'=>'Type at least 2 characters.'];$cfg=sk1040_settings();$max=max(6,min(40,(int)$cfg['max_results']));$intent=sk1040_intents($query);$types=$intent?:['business','product','property','doctor','restaurant','hotel','job','event'];$all=[];$per=max(2,(int)ceil($max/max(1,count($types))));foreach($types as $type){$searchFor=$query;$rows=match($type){'business'=>sk1040_generic_search('businesses','business',$searchFor,['name','description','tagline','address','area'],$per),'product'=>sk1040_generic_search('store_products','product',$searchFor,['title','name','short_description','description'],$per),'property'=>sk1040_generic_search('city_portal_items','property',$searchFor,['title','summary','description','address'],$per,['content_type'=>'property']),'job'=>sk1040_generic_search('city_portal_items','job',$searchFor,['title','summary','description','address'],$per,['content_type'=>'job']),'event'=>sk1040_generic_search('city_portal_items','event',$searchFor,['title','summary','description','address'],$per,['content_type'=>'event']),'doctor'=>sk1040_generic_search('health_doctors_v580','doctor',$searchFor,['name','full_name','display_name','specialization','bio'],$per),'restaurant'=>sk1040_generic_search('tourism_restaurants_v700','restaurant',$searchFor,['name','description','cuisine','address','area'],$per),'hotel'=>sk1040_generic_search('tourism_hotels_v700','hotel',$searchFor,['name','description','address','area'],$per),default=>[]};if(!$rows&&$intent){$rows=match($type){'business'=>sk1040_generic_search('businesses','business','',['name'],$per),'product'=>sk1040_generic_search('store_products','product','',['title','name'],$per),'property'=>sk1040_generic_search('city_portal_items','property','',['title'],$per,['content_type'=>'property']),'job'=>sk1040_generic_search('city_portal_items','job','',['title'],$per,['content_type'=>'job']),'event'=>sk1040_generic_search('city_portal_items','event','',['title'],$per,['content_type'=>'event']),'doctor'=>sk1040_generic_search('health_doctors_v580','doctor','',['name','full_name','display_name'],$per),'restaurant'=>sk1040_generic_search('tourism_restaurants_v700','restaurant','',['name'],$per),'hotel'=>sk1040_generic_search('tourism_hotels_v700','hotel','',['name'],$per),default=>[]};}$all=array_merge($all,$rows);if(count($all)>=$max)break;}
 // Useful contacts are included only for explicit emergency-like searches.
 $l=mb_strtolower($query);if((str_contains($l,'emergency')||str_contains($l,'ambulance')||str_contains($l,'police')||str_contains($l,'pharmacy'))&&sk1040_table_exists('customer_emergency_contacts_v1030')){try{$q=db()->prepare('SELECT * FROM customer_emergency_contacts_v1030 WHERE tenant_id=? AND enabled=1 AND (label LIKE ? OR category_key LIKE ? OR note LIKE ?) ORDER BY sort_order,id DESC LIMIT 6');$like='%'.$query.'%';$q->execute([sk1040_tid(),$like,$like,$like]);foreach($q->fetchAll()?:[] as $r)$all[]=['type'=>'contact','id'=>(int)$r['id'],'title'=>(string)$r['label'],'subtitle'=>(string)($r['note']??$r['address']??''),'image'=>'','price'=>'','url'=>'tel:'.preg_replace('/[^0-9+]/','',(string)$r['phone']),'bookable'=>false,'provider_user_id'=>0];}catch(Throwable $e){}}
 $all=array_slice($all,0,$max);if(sk1040_on('search_logging')&&sk1040_table_exists('local_assistant_searches_v1040')){try{$q=db()->prepare('INSERT INTO local_assistant_searches_v1040(tenant_id,user_id,visitor_hash,query_text,intent_json,result_count,created_at) VALUES(?,?,?,?,?,?,NOW())');$q->execute([sk1040_tid(),sk1040_uid()?:null,sk1040_visitor_hash(),mb_substr($query,0,250),json_encode($intent,JSON_UNESCAPED_UNICODE),count($all)]);}catch(Throwable $e){}}
 $msg=$all?'I found '.count($all).' local option'.(count($all)===1?'':'s').' for you.':'I could not find an exact match. Try a simpler service, business, product, doctor, hotel or property name.';return ['query'=>$query,'results'=>$all,'intent'=>$intent,'message'=>$msg];}
function sk1040_suggestions(int $limit=12): array {if(!sk1040_table_exists('local_assistant_suggestions_v1040'))return [];try{$q=db()->prepare('SELECT * FROM local_assistant_suggestions_v1040 WHERE tenant_id=? AND enabled=1 ORDER BY sort_order,id LIMIT '.max(1,min(30,$limit)));$q->execute([sk1040_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1040_entity_snapshot(string $type,int $id): array {$maps=['business'=>['businesses',['name','title'],['owner_user_id','owner_id']],'doctor'=>['health_doctors_v580',['name','full_name','display_name'],['user_id','owner_user_id']],'hotel'=>['tourism_hotels_v700',['name','title'],['owner_user_id']],'restaurant'=>['tourism_restaurants_v700',['name','title'],['owner_user_id']]];if(!isset($maps[$type])||$id<1)return [];$table=$maps[$type][0];if(!sk1040_table_exists($table))return [];$cols=sk1040_columns($table);$where=['id=?'];$p=[$id];$tid=sk1040_tid();if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='tenant_id=?';$p[]=$tid;}try{$q=db()->prepare('SELECT * FROM `'.$table.'` WHERE '.implode(' AND ',$where).' LIMIT 1');$q->execute($p);$r=$q->fetch();if(!$r)return [];$provider=0;foreach($maps[$type][2] as $k)if(isset($r[$k])&&(int)$r[$k]>0){$provider=(int)$r[$k];break;}return ['type'=>$type,'id'=>$id,'title'=>sk1040_title($r),'provider_user_id'=>$provider,'business_id'=>$type==='business'?$id:0,'row'=>$r];}catch(Throwable $e){return [];}}
function sk1040_booking_no(): string {return 'SKB-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));}
function sk1040_create_booking(array $d): int {if(!sk1040_on('booking'))throw new RuntimeException('Bookings are disabled.');$uid=sk1040_uid();if($uid<1&&!sk1040_on('guest_booking'))throw new RuntimeException('Please login to create a booking.');$type=substr(preg_replace('/[^a-z_]/','',mb_strtolower((string)($d['entity_type']??''))),0,30);$id=(int)($d['entity_id']??0);$entity=sk1040_entity_snapshot($type,$id);if(!$entity)throw new InvalidArgumentException('The selected booking target is not available.');$name=trim((string)($d['customer_name']??''));$phone=trim((string)($d['customer_phone']??''));if($name===''||$phone==='')throw new InvalidArgumentException('Name and phone are required.');$date=trim((string)($d['booking_date']??''));$time=trim((string)($d['booking_time']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$time))throw new InvalidArgumentException('Select a valid date and time.');$requested=$date.' '.$time.':00';$ts=strtotime($requested);$notice=max(0,(int)sk1040_settings()['booking_min_notice_minutes']);if(!$ts||$ts<time()+$notice*60)throw new InvalidArgumentException('Please select a later booking time.');$party=max(1,min(50,(int)($d['party_size']??1)));$notes=mb_substr(trim((string)($d['notes']??'')),0,1200);$no=sk1040_booking_no();$q=db()->prepare("INSERT INTO unified_bookings_v1040(tenant_id,booking_no,user_id,visitor_hash,entity_type,entity_id,entity_title,provider_user_id,business_id,customer_name,customer_phone,customer_whatsapp,requested_at,party_size,notes,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending',NOW(),NOW())");$q->execute([sk1040_tid(),$no,$uid?:null,sk1040_visitor_hash(),$type,$id,mb_substr((string)$entity['title'],0,190),(int)$entity['provider_user_id'],(int)$entity['business_id'],mb_substr($name,0,120),mb_substr($phone,0,50),mb_substr(trim((string)($d['customer_whatsapp']??'')),0,50),$requested,$party,$notes]);$bid=(int)db()->lastInsertId();sk1040_log_status($bid,'pending','Booking requested',$uid?:null);return $bid;}
function sk1040_log_status(int $bookingId,string $status,string $note='',?int $actor=null): void {if(!sk1040_table_exists('unified_booking_status_log_v1040'))return;try{$q=db()->prepare('INSERT INTO unified_booking_status_log_v1040(tenant_id,booking_id,status,note,actor_user_id,created_at) VALUES(?,?,?,?,?,NOW())');$q->execute([sk1040_tid(),$bookingId,mb_substr($status,0,40),mb_substr($note,0,500),$actor]);}catch(Throwable $e){}}
function sk1040_my_bookings(int $limit=60): array {if(!sk1040_table_exists('unified_bookings_v1040'))return [];$uid=sk1040_uid();$where=['tenant_id=?'];$p=[sk1040_tid()];if($uid>0){$where[]='user_id=?';$p[]=$uid;}else{$where[]='visitor_hash=?';$p[]=sk1040_visitor_hash();}try{$q=db()->prepare('SELECT * FROM unified_bookings_v1040 WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT '.max(1,min(100,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1040_customer_cancel(int $id): void {$uid=sk1040_uid();$where=['id=?','tenant_id=?'];$p=[$id,sk1040_tid()];if($uid>0){$where[]='user_id=?';$p[]=$uid;}else{$where[]='visitor_hash=?';$p[]=sk1040_visitor_hash();}$where[]="status IN ('pending','confirmed','reschedule_requested')";$q=db()->prepare("UPDATE unified_bookings_v1040 SET status='cancelled',updated_at=NOW() WHERE ".implode(' AND ',$where));$q->execute($p);if($q->rowCount()<1)throw new RuntimeException('Booking cannot be cancelled.');sk1040_log_status($id,'cancelled','Cancelled by customer',$uid?:null);}
function sk1040_provider_bookings(int $uid,int $limit=100): array {if($uid<1||!sk1040_table_exists('unified_bookings_v1040'))return [];try{$q=db()->prepare('SELECT * FROM unified_bookings_v1040 WHERE tenant_id=? AND provider_user_id=? ORDER BY FIELD(status,\'pending\',\'reschedule_requested\',\'confirmed\',\'completed\',\'cancelled\',\'rejected\'),requested_at ASC,id DESC LIMIT '.max(1,min(200,$limit)));$q->execute([sk1040_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1040_provider_update(int $uid,int $id,string $status,string $note='',string $newDate='',string $newTime=''): void {$allowed=['confirmed','reschedule_requested','completed','rejected','cancelled'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('Invalid status.');$q=db()->prepare('SELECT * FROM unified_bookings_v1040 WHERE id=? AND tenant_id=? AND provider_user_id=? LIMIT 1');$q->execute([$id,sk1040_tid(),$uid]);$b=$q->fetch();if(!$b)throw new RuntimeException('Booking not found for this provider.');$requested=(string)$b['requested_at'];if($status==='reschedule_requested'&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$newDate)&&preg_match('/^\d{2}:\d{2}$/',$newTime))$requested=$newDate.' '.$newTime.':00';$u=db()->prepare('UPDATE unified_bookings_v1040 SET status=?,requested_at=?,provider_note=?,updated_at=NOW(),confirmed_at=CASE WHEN ?=\'confirmed\' THEN NOW() ELSE confirmed_at END WHERE id=?');$u->execute([$status,$requested,mb_substr($note,0,800),$status,$id]);sk1040_log_status($id,$status,$note,$uid);$customer=(int)($b['user_id']??0);if($customer>0&&sk1040_table_exists('customer_utility_alerts_v1030')){try{$title='Booking '.ucwords(str_replace('_',' ',$status));$body=(string)$b['entity_title'].' · '.date('d M Y h:i A',strtotime($requested));db()->prepare('INSERT INTO customer_utility_alerts_v1030(tenant_id,user_id,alert_type,title,body,target_url,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([sk1040_tid(),$customer,'booking_'.$status,$title,$body,'/my-bookings-v1040.php']);}catch(Throwable $e){}}}
function sk1040_provider_entities(int $uid): array {$out=[];$maps=[['businesses','business',['owner_user_id','owner_id']],['health_doctors_v580','doctor',['user_id','owner_user_id']],['tourism_hotels_v700','hotel',['owner_user_id']],['tourism_restaurants_v700','restaurant',['owner_user_id']]];foreach($maps as [$table,$type,$ownerFields]){if(!sk1040_table_exists($table))continue;$cols=sk1040_columns($table);$owns=[];foreach($ownerFields as $f)if(in_array($f,$cols,true))$owns[]="`$f`=?";if(!$owns)continue;$where=['('.implode(' OR ',$owns).')'];$p=array_fill(0,count($owns),$uid);$tid=sk1040_tid();if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='tenant_id=?';$p[]=$tid;}try{$q=db()->prepare('SELECT * FROM `'.$table.'` WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 60');$q->execute($p);foreach($q->fetchAll()?:[] as $r)$out[]=['type'=>$type,'id'=>(int)$r['id'],'title'=>sk1040_title($r)];}catch(Throwable $e){}}return $out;}
function sk1040_availability(int $uid): array {if(!sk1040_table_exists('booking_availability_v1040'))return [];try{$q=db()->prepare('SELECT * FROM booking_availability_v1040 WHERE tenant_id=? AND provider_user_id=? ORDER BY entity_type,entity_id,day_of_week,start_time');$q->execute([sk1040_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1040_save_availability(int $uid,array $d): void {$type=substr(preg_replace('/[^a-z_]/','',(string)($d['entity_type']??'')),0,30);$id=(int)($d['entity_id']??0);$ok=false;foreach(sk1040_provider_entities($uid) as $e)if($e['type']===$type&&(int)$e['id']===$id){$ok=true;break;}if(!$ok)throw new RuntimeException('This entity is not owned by your account.');$day=max(0,min(6,(int)($d['day_of_week']??0)));$start=(string)($d['start_time']??'09:00');$end=(string)($d['end_time']??'17:00');if(!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$start>=$end)throw new InvalidArgumentException('Invalid time range.');$slot=max(10,min(240,(int)($d['slot_minutes']??30)));$q=db()->prepare('INSERT INTO booking_availability_v1040(tenant_id,provider_user_id,entity_type,entity_id,day_of_week,start_time,end_time,slot_minutes,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE start_time=VALUES(start_time),end_time=VALUES(end_time),slot_minutes=VALUES(slot_minutes),enabled=1,updated_at=NOW()');$q->execute([sk1040_tid(),$uid,$type,$id,$day,$start,$end,$slot]);}
function sk1040_delete_availability(int $uid,int $id): void {db()->prepare('DELETE FROM booking_availability_v1040 WHERE id=? AND tenant_id=? AND provider_user_id=?')->execute([$id,sk1040_tid(),$uid]);}
function sk1040_stats(): array {$out=['searches_today'=>0,'bookings_pending'=>0,'bookings_confirmed'=>0,'bookings_total'=>0];try{if(sk1040_table_exists('local_assistant_searches_v1040')){$q=db()->prepare('SELECT COUNT(*) FROM local_assistant_searches_v1040 WHERE tenant_id=? AND created_at>=CURDATE()');$q->execute([sk1040_tid()]);$out['searches_today']=(int)$q->fetchColumn();}if(sk1040_table_exists('unified_bookings_v1040')){$q=db()->prepare("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='confirmed') confirmed FROM unified_bookings_v1040 WHERE tenant_id=?");$q->execute([sk1040_tid()]);$r=$q->fetch()?:[];$out['bookings_total']=(int)($r['total']??0);$out['bookings_pending']=(int)($r['pending']??0);$out['bookings_confirmed']=(int)($r['confirmed']??0);}}catch(Throwable $e){}return $out;}
